export function betaFlexGuideEnabled(account: { workspace?: string; profileType?: string; onboardingBeta?: boolean; activationStage?: string | null }, isolatedBeta?: boolean) {
  return Boolean(isolatedBeta && account.workspace === "workforce" && account.profileType === "workforce"
    && account.onboardingBeta && account.activationStage?.startsWith("amazon_email_pilot:"));
}
